import {LOCATIONS} from './engine.js';
const pos={HD:[140,15,40,42],RT:[78,65,52,101],CT:[139,62,42,112],LT:[190,65,52,101],RA:[22,78,42,133],LA:[256,78,42,133],RL:[88,200,54,150],LL:[178,200,54,150]};
const paths={HD:'M146 15 L174 15 180 30 177 54 143 54 140 30Z',CT:'M140 62 L180 62 182 147 174 174 146 174 138 147Z',RT:'M78 65 L130 65 136 150 121 171 88 162 92 127 76 100Z',LT:'M190 65 L242 65 244 100 228 127 232 162 199 171 184 150Z',RA:'M22 78 L63 78 68 105 59 132 64 157 59 208 26 211 20 162 26 130 17 105Z',LA:'M257 78 L298 78 303 105 294 130 300 162 294 211 261 208 256 157 261 132 252 105Z',RL:'M92 200 L141 200 141 250 132 279 138 326 143 349 82 349 92 326 87 279 94 250Z',LL:'M179 200 L228 200 226 250 233 279 228 326 238 349 177 349 182 326 188 279 179 250Z'};

const quadPos={HD:[139,20,42,45],RT:[90,95,40,98],CT:[138,94,44,113],LT:[190,95,40,98],RA:[25,82,52,124],LA:[243,82,52,124],RL:[25,225,52,118],LL:[243,225,52,118]};
const quadPaths={
 HD:'M139 21 L181 21 L181 61 L139 61Z',
 CT:'M137 94 L183 94 L186 195 L179 207 L141 207 L134 195Z',
 RT:'M91 96 L128 96 L132 185 L112 193 L90 185Z',
 LT:'M192 96 L229 96 L230 185 L208 193 L188 185Z',
 RA:'M25 82 L76 82 L78 119 L69 160 L75 201 L27 201 L34 160 L23 119Z',
 LA:'M244 82 L295 82 L297 119 L288 160 L294 201 L246 201 L253 160 L242 119Z',
 RL:'M25 225 L76 225 L78 262 L68 296 L76 341 L25 341 L33 296 L23 262Z',
 LL:'M244 225 L295 225 L297 262 L287 296 L295 341 L244 341 L252 296 L242 262Z'
};
const bipedDiagramLabels="<g font-family=\"Arial\" font-size=\"8\" fill=\"#111\" text-anchor=\"middle\"><text x=\"160\" y=\"10\">Голова</text><text x=\"105\" y=\"59\">Правый торс</text><text x=\"215\" y=\"59\">Левый торс</text><text x=\"160\" y=\"185\">Центр торса</text><text x=\"43\" y=\"226\">Правая рука</text><text x=\"277\" y=\"226\">Левая рука</text><text x=\"112\" y=\"363\">Правая нога</text><text x=\"208\" y=\"363\">Левая нога</text><text x=\"160\" y=\"384\">○ цело · ● повреждено</text></g>";
const quadDiagramLabels="<g font-family=\"Arial\" font-size=\"9\" fill=\"#111\" text-anchor=\"middle\"><text x=\"160\" y=\"9\">ПЕРЕД</text><text x=\"160\" y=\"76\">Голова</text><text x=\"107\" y=\"84\">Правый торс</text><text x=\"213\" y=\"84\">Левый торс</text><text x=\"160\" y=\"224\">Центр торса</text><text x=\"51\" y=\"213\">Правая передняя нога</text><text x=\"270\" y=\"213\">Левая передняя нога</text><text x=\"52\" y=\"362\">Правая задняя нога</text><text x=\"266\" y=\"362\">Левая задняя нога</text><text x=\"160\" y=\"382\">○ цело · ● повреждено</text></g>";
const bipedConnections='M149 55V62M171 55V62M130 78H140M180 78H190M64 92H78M242 92H256M133 169L140 190H180L187 169M140 190L118 200M180 190L202 200';
const quadConnections='M146 60L146 94M174 60L174 94M90 114H76M230 114H244M90 240H76M230 240H244M134 190L112 225M186 190L208 225';
const locationNames=u=>u.config==='Quad'?{...LOCATIONS,
 RA:'Правая передняя нога',LA:'Левая передняя нога',
 RL:'Правая задняя нога',LL:'Левая задняя нога'}:LOCATIONS;
function diagram(u,internal=false){const quad=u.config==='Quad',shapePaths=quad?quadPaths:paths,shapePositions=quad?quadPos:pos;let data=internal?u.structure:u.armor,max=internal?u.maxStructure:u.maxArmor;return `<svg class="mechdiagram" viewBox="0 0 320 390" role="img" aria-label="${internal?'Внутренняя структура':'Броня'} ${u.name}"><g fill="#fafafa" stroke="#171717" stroke-width="1.7"><path d="${quad?quadConnections:bipedConnections}" fill="none"/>${Object.entries(shapePaths).map(([l,d])=>`<path d="${d}"/>`).join('')}</g>${Object.keys(shapePositions).map(l=>{const [x,y,w,h]=shapePositions[l],cols=l==='HD'?3:l==='CT'?3:4,space=9,n=max[l],rows=Math.ceil(n/cols),startX=x+w/2-(cols-1)*space/2,startY=y+12,vertical=l==='HD'?9:Math.min(22,(h-40)/Math.max(1,rows-1));let dots='';for(let i=0;i<n;i++){const cx=startX+(i%cols)*space,cy=startY+Math.floor(i/cols)*vertical;dots+=`<circle cx="${cx}" cy="${cy}" r="3" fill="${i<data[l]?'white':'#171717'}" stroke="#171717" stroke-width=".85"/>`;}return `<g><title>${locationNames(u)[l]}: ${data[l]} / ${max[l]}</title>${dots}<text x="${l==='HD'?200:x+w/2}" y="${l==='HD'?38:y+h-12}" text-anchor="middle" font-size="8" fill="#111">${data[l]}/${max[l]}</text></g>`;}).join('')}${quad?quadDiagramLabels:bipedDiagramLabels}</svg>`;}
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const box=(title,content,cls='')=>`<section class="recordbox ${cls}"><h3>${title}</h3>${content}</section>`;
const slotName=(u,s)=>!s?'—':s.startsWith('w:')?u.weapons[+s.split(':')[1]].name:s.startsWith('ammo:')?'Боезапас '+u.weapons[+s.split(':')[1]].name:({life:'Жизнеобеспечение',sensors:'Датчики',cockpit:'Кабина',engine:'Двигатель',gyro:'Гироскоп',shoulder:'Плечо',upper:'Верхний актуатор',lower:'Нижний актуатор',hand:'Кисть',hip:'Бедро',foot:'Стопа',hatchet:'Топор',sink:'Радиатор',jump:'Прыжковый двигатель'}[s]||s);
export function recordSheet(u){const locNames=locationNames(u);const equipment=Object.entries(locNames).map(([l,name])=>`<div class="equipmentloc"><b>${name}</b>${u.slots[l].map((s,i)=>`<div style="${u.crit[l][i]?'text-decoration:line-through;color:#a33':''}">${i+1}. ${u.crit[l][i]?'●':'○'} ${slotName(u,s)}</div>`).join('')}<small>Структура: ${u.structure[l]} / ${u.maxStructure[l]}</small></div>`).join('');return `<article class="recordpaper"><header class="recordhead"><div class="recordbrand">BATTLETECH<small>’MECH RECORD SHEET / ЛИСТ МЕХА</small></div><div>${u.variant}<br><b>${u.name.toUpperCase()}</b></div></header><div class="recordcolumns"><div class="recordleft"><div class="recordtop">${box('’MECH DATA / ДАННЫЕ МЕХА',`<div class="recordfacts"><b>Тип: ${u.name} ${u.variant}</b><span>Масса: <b>${u.tonnage} т</b></span><span>Технология: Inner Sphere</span><span>Шасси: <b>${u.config==='Quad'?'Quad (диагностическая схема)':'Biped'}</b></span><span>Ходьба: <b>${u.walk}</b></span><span>Бег: <b>${Math.ceil(u.walk*1.5)}</b></span><span>Прыжок: <b>${u.jump}</b></span></div>`)}${box('WARRIOR / МЕХВОИН',`<div class="recordfacts"><b>${escapeText(u.pilotName||'Пилот '+(u.id+1))} / ${u.team?'Красный':'Зелёный'} отряд</b><span>Стрельба: <b>${u.gunnery}</b></span><span>Пилотирование: <b>${u.piloting}</b></span><span>Состояние: <b>${u.dead?'Уничтожен':u.shutdown?'Отключён':'В строю'}</b></span><small>Ранения: ${u.pilotWounds}/6 · ${u.pilotWounds>=6?'Погиб':u.unconscious?'Без сознания':'В сознании'}</small><small>Порог сознания: ${u.pilotWounds>=6?'—':([0,3,5,7,10,11][u.pilotWounds]||'—')}</small></div>`)}</div>${box('WEAPONS & EQUIPMENT / ВООРУЖЕНИЕ',`<table><thead><tr><th>Оружие</th><th>Лок.</th><th>Тепло</th><th>Урон</th><th>Мин.</th><th>Бл.</th><th>Ср.</th><th>Дал.</th><th>Боезапас</th></tr></thead><tbody>${u.weapons.map(w=>`<tr><td>${w.name}</td><td>${w.location}</td><td>${w.heat}</td><td>${w.rack?w.rack+'×'+w.damage:w.damage}</td><td>${w.min||'—'}</td>${w.ranges.map(n=>`<td>${n}</td>`).join('')}<td>${w.ammo??'∞'}</td></tr>`).join('')}</tbody></table><div class="recordsummary">Броня: ${[...Object.values(u.armor),...Object.values(u.rear)].reduce((a,b)=>a+b,0)} / ${[...Object.values(u.maxArmor),...Object.values(u.maxRear)].reduce((a,b)=>a+b,0)} · Радиаторы: ${u.sinks-u.sinksLost}</div>`)}${box('CRITICAL HIT TABLE / ОБОРУДОВАНИЕ ПО СЕКЦИЯМ',`<p class="recordnote">Реальные слоты по листу шасси. Повреждённые компоненты зачёркнуты.</p><div class="equipmentgrid">${equipment}</div><div class="transfer"><b>ПЕРЕНОС ПОВРЕЖДЕНИЙ</b>${u.config==='Quad'?'<span>Передняя и задняя правая нога → правый торс → центр торса</span><span>Передняя и задняя левая нога → левый торс → центр торса</span>':'<span>Правая рука / нога → правый торс → центр торса</span><span>Левая рука / нога → левый торс → центр торса</span>'}</div>`,'recordcritical')}<p class="recordnote">Фан-адаптация A Game of Armored Combat. Компоновка по образцу листа из книги; значения отражают текущий бой. Кормовая броня, критические попадания и ранения пилота обновляются по состоянию боя.</p></div><div class="recordright">${box('ARMOR DIAGRAM / СХЕМА БРОНИ',diagram(u)+`<div class="reararmor">${['RT','CT','LT'].map(l=>`<div><b>${locNames[l]} · корма</b><p>${Array.from({length:u.maxRear[l]},(_,i)=>i<u.rear[l]?'○':'●').join('')}</p><span>${u.rear[l]} / ${u.maxRear[l]}</span></div>`).join('')}</div>`,'armorbox')}<div class="recordbottom">${box('INTERNAL STRUCTURE / СТРУКТУРА',diagram(u,true),'structurebox')}<div class="heatscale"><b>HEAT<br>ТЕПЛО</b><span class="heat-overflow" title="Heat Overflow / нагрев сверх 30">+${Math.max(0,u.heat-30)}</span><div>${Array.from({length:31},(_,i)=>30-i).map(n=>`<span class="${n>0&&n<=u.heat?'filled':''} ${n===u.heat?'current':''}">${n}</span>`).join('')}</div></div></div>${box('HEAT DATA / НАГРЕВ',`<div class="heatcurrent">${u.heat} <small>+ ${u.pendingHeat} за ход</small></div><p><span class="sink-status" aria-label="Рабочие и повреждённые теплоотводы">Теплоотводы: ${u.sinks-u.sinksLost} / ${u.sinks} · ${Array.from({length:u.sinks},(_,i)=>i<u.sinks-u.sinksLost?'○':'●').join('')}</span><br>Охлаждение: −${u.sinks-u.sinksLost} / ход<br>Сухая местность, без тепла двигателя: <b>${Math.max(0,u.heat+u.pendingHeat-u.sinks+u.sinksLost)}</b></p><table><tr><td>5 / 10 / 15 / 20 / 25</td><td>−1 / −2 / −3 / −4 / −5 к ходу</td></tr><tr><td>8 / 13 / 17 / 24</td><td>+1 / +2 / +3 / +4 к стрельбе</td></tr><tr><td>14 / 18 / 22 / 26</td><td>Реактор: 4+ / 6+ / 8+ / 10+</td></tr><tr><td>19 / 23 / 28</td><td>Боезапас: 4+ / 6+ / 8+</td></tr><tr><td>30</td><td>Автоматическое отключение</td></tr></table>`,'heatbox')}</div></div><div class="recordfoot">IRON HEX · ${u.variant} · LIVE RECORD &nbsp; | &nbsp; ○ неповреждено &nbsp; ● потеряно</div></article>`;}
